class Solution {
    public int numberOfMatches(int n) {
        int matches = 0;
        while (n > 1) {
            matches += n / 2;
            n = (n + 1) / 2;
        }
        return matches;
    }
}

class Solution {
    public int numberOfMatches(int n) {
        if (n == 1) {
            return 0;
        }
        int matchesThisRound = n / 2;
        int teamsNextRound = (n + 1) / 2;
        return matchesThisRound + numberOfMatches(teamsNextRound);
    }
}
